# Import of required libraries
import re
import skyramp
import os
import time

from SkyrampUtils import (
    build_headers,
    create_work_pool,
    filter_work_pools,
    get_work_pools,
)


# URL for test requests
URL_localhost = skyramp.get_base_url("SKYRAMP_TEST_BASE_URL", "http://localhost:4200")

UUID_RE = r"^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$"


def test_integration():
    # Invocation of Skyramp Client
    client = skyramp.Client()
    headers = build_headers()

    pool_name = skyramp.unique_suffix("sk-slots-pool")

    endpoint_1_POST_response = create_work_pool(client, headers, pool_name)

    assert skyramp.get_response_value(endpoint_1_POST_response, "name") == pool_name
    assert skyramp.get_response_value(endpoint_1_POST_response, "type") == "process"
    assert skyramp.get_response_value(endpoint_1_POST_response, "concurrency_limit") == 5
    assert skyramp.get_response_value(endpoint_1_POST_response, "concurrency_limit") >= 1
    assert skyramp.get_response_value(endpoint_1_POST_response, "is_paused") is False
    assert skyramp.get_response_value(endpoint_1_POST_response, "status") == "NOT_READY"
    assert skyramp.get_response_value(endpoint_1_POST_response, "active_slots") == 0
    assert re.match(
        UUID_RE, str(skyramp.get_response_value(endpoint_1_POST_response, "id")), re.I
    )
    assert re.match(
        UUID_RE,
        str(skyramp.get_response_value(endpoint_1_POST_response, "default_queue_id")),
        re.I,
    )
    assert re.match(
        r"^\d{4}-\d{2}-\d{2}T",
        str(skyramp.get_response_value(endpoint_1_POST_response, "created")),
    )
    assert skyramp.check_schema(endpoint_1_POST_response, r'''{"description": null}''')

    pool_id = skyramp.get_response_value(endpoint_1_POST_response, "id")

    endpoint_1_GET_response = get_work_pools(client, headers)

    list_index = -1
    scan_index = 0
    while skyramp.get_response_value(endpoint_1_GET_response, f"{scan_index}.id") is not None:
        if skyramp.get_response_value(endpoint_1_GET_response, f"{scan_index}.id") == pool_id:
            list_index = scan_index
        scan_index += 1
    assert scan_index >= 1
    assert list_index >= 0
    assert (
        skyramp.get_response_value(endpoint_1_GET_response, f"{list_index}.id")
        == pool_id
    )
    assert (
        skyramp.get_response_value(endpoint_1_GET_response, f"{list_index}.name")
        == pool_name
    )
    assert (
        skyramp.get_response_value(endpoint_1_GET_response, f"{list_index}.type")
        == "process"
    )
    assert (
        skyramp.get_response_value(
            endpoint_1_GET_response, f"{list_index}.concurrency_limit"
        )
        == 5
    )
    assert (
        skyramp.get_response_value(
            endpoint_1_GET_response, f"{list_index}.active_slots"
        )
        == 0
    )

    filter_POST_response = filter_work_pools(client, headers)

    filter_index = -1
    filter_scan_index = 0
    while skyramp.get_response_value(filter_POST_response, f"{filter_scan_index}.id") is not None:
        if skyramp.get_response_value(filter_POST_response, f"{filter_scan_index}.id") == pool_id:
            filter_index = filter_scan_index
        filter_scan_index += 1
    assert filter_scan_index <= 200
    assert filter_index >= 0
    assert (
        skyramp.get_response_value(filter_POST_response, f"{filter_index}.id")
        == pool_id
    )
    assert (
        skyramp.get_response_value(
            filter_POST_response, f"{filter_index}.concurrency_limit"
        )
        == 5
    )
    assert (
        skyramp.get_response_value(filter_POST_response, f"{filter_index}.active_slots")
        == 0
    )
    assert skyramp.get_response_value(
        endpoint_1_GET_response, f"{list_index}.active_slots"
    ) == skyramp.get_response_value(
        filter_POST_response, f"{filter_index}.active_slots"
    )
    assert scan_index == filter_scan_index


if __name__ == "__main__":
    test_integration()
